import {weatherCat as cat} from '../pixel/cats.js';
import {scenery,catWeather} from './atmosphere.js';
import {state,esc,totalProgress,minutes,fmt,dateKey,currentProfile} from '../../lib/store.js';
import {destinations} from '../hud/home.js';
import {icon,bar,button,panel} from '../pixel/primitives.js';
import {moodForm} from '../life/life.js';
import {weatherPanel} from '../weather/weather.js';
export {weatherCat as cat} from '../pixel/cats.js';
export function shell(route,body){const name=esc(currentProfile()?.displayName||'Guest');return `<aside class="side-nav"><a class="home-brand" href="#home">double's home</a><small>v0.4 · LOCAL</small><nav aria-label="城市区域">${destinations.map(([id,en])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(id,32)}<span>${en}</span></a>`).join('')}</nav><div class="side-bottom"><div class="city-thumb"></div><p>GOOD NIGHT,<br>${name}.</p><span>LV.02</span>${bar(totalProgress(),'经验','magenta')}</div></aside><header class="system-top"><span id="os-date"></span><b id="os-clock"></b><div class="music" title="尚未加载音频">♪ lofi_chill.mp3 <span class="muted">　◀　Ⅱ　▶ ━━━　UI ONLY</span></div><button class="profile-chip" data-action="settings" title="Local profile">${name} · LOCAL</button><button data-action="navigate" data-value="vault" aria-label="打开资料库">${icon('training')}</button><button data-action="effects" aria-pressed="${state.effects}">FX ${state.effects?'ON':'OFF'}</button><button data-action="settings" aria-label="设置">▦</button></header>${body}<div class="crt" aria-hidden="true"></div>`}
function smallWeather(){const w=state.weather;return `<div class="weather-mini">${icon(w?.current.weather_code>3?'rain':'cloud',42)}<strong>${w?Math.round(w.current.temperature_2m)+'°C':'--°C'}</strong><span>${esc(w?.city||'选择城市')}<br>RAIN ${w?.daily.precipitation_probability_max[0]??'--'}%</span></div><div class="cat-advice">${cat(catWeather(w))}<p>${w?((w.daily.precipitation_probability_max[0]||0)>=40?'今晚出门记得带伞。':'查看天气，安排今天的出行。'):'选择城市后显示真实天气。'}</p></div>${button(w?'详细天气':'选择城市',w?'room':'city-search')}`}
export function cityScreen(){const progress=totalProgress(),m=state.moods[dateKey()],quest=state.tasks.find(t=>String(t.id)===state.mainQuestId)||state.tasks.find(t=>!t.done&&t.cat==='论文'),deadlineTime=Date.parse(`${state.deadline}T23:59:59`),hasProject=Boolean(String(state.thesisTitle||'').trim()),days=Number.isFinite(deadlineTime)?Math.ceil((deadlineTime-Date.now())/86400000):null,questPanel=hasProject?`<div class="quest-main">${icon('research',38)}<div>MASTER THESIS<p>${esc(quest?.text||'今日主线已完成')}</p>${days===null?'':`<strong>T ${days>=0?'−':'+'} ${Math.abs(days)} DAYS</strong>`}</div></div>${bar(progress,'论文进度','magenta')}<a href="#research">${progress}% / RESEARCH LAB →</a>`:`<div class="quest-main">${icon('research',38)}<div><strong>NO MAIN QUEST YET</strong><p>在研究区建立你的项目。</p></div></div><a href="#research">SET RESEARCH PROJECT →</a>`;return `<section class="city-scene">${scenery('city',state.weather)}<div class="scene-links">${destinations.slice(1).map(([id,en,zh])=>`<a class="district district-${id}" href="#${id}">${icon(id,30)}<div><b>${en}</b><p>${zh}</p><small>${id==='research'?'当前进度 '+progress+'%':id==='life'?'RETURN HOME →':id==='mission'?'QUEST LOG / LOCAL ONLY':id==='training'?'C1 备考中':'ENTER TERMINAL →'}</small></div></a>`).join('')}<div class="district district-core">${icon('home',28)}<div>CONTROL CORE<p>double's home</p><small>SYSTEM ONLINE</small></div></div></div><div class="city-bottom">${panel('MAIN QUEST',questPanel)}${panel('TODAY TASKS',state.tasks.slice().sort((a,b)=>Number(a.done)-Number(b.done)).slice(0,5).map(t=>`<label class="mini-task ${t.done?'done':''}"><input type="checkbox" data-change="task" data-id="${esc(t.id)}" ${t.done?'checked':''}><span>${esc(t.text)}</span></label>`).join(''),button('＋','new-task'))}${panel('STATUS',`<a href="#focus">FOCUS <b>${fmt(minutes('today'))}</b></a>${bar(Math.min(100,minutes('today')/2.4),'专注','magenta')}<a href="#training">PORTUGUESE <b>C1 READY</b></a>${bar(state.trainingDays.includes(dateKey())?100:65,'葡语')}<a href="#life">MOOD <b>${m?.energy??'—'} / 10</b></a>${bar((m?.energy||0)*10,'心情','green')}`)}${panel('WEATHER',smallWeather())}</div></section>`}
let calendarDate=new Date();export function calendarMove(n){calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+n,1)}
function calendar(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),offset=(new Date(y,m,1).getDay()+6)%7,count=new Date(y,m+1,0).getDate();return panel('CALENDAR',`<div class="row">${button('‹','calendar-prev')}<b>${y}.${String(m+1).padStart(2,'0')}</b>${button('›','calendar-next')}</div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(x=>`<span>${x}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<button class="${d===dateKey()?'today':''}" data-action="calendar-day" data-value="${d}" aria-label="查看 ${d} 日记">${i+1}</button>`}).join('')}</div>`)}
export function roomScreen(ui){const items=state.finance.filter(f=>f.date.startsWith(ui.financeMonth)),sum=k=>items.filter(f=>f.kind===k).reduce((a,f)=>a+f.amount,0),income=sum('income'),expense=sum('expense');return `<section class="apartment-scene">${scenery('apartment',state.weather)}<a class="enter-city" href="#home">← ENTER CITY</a><div class="room-weather">${weatherPanel()}</div><div class="room-calendar">${calendar()}</div><div class="room-mood">${panel('MOOD.exe',moodForm())}</div><div class="room-diary">${panel('DIARY.log',`<p class="micro">${dateKey()}</p>${state.diaries.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(d=>`<button class="diary-line" data-action="diary-edit" data-id="${d.id}">◆ ${esc(d.title)} <small>${esc(d.content.slice(0,42))}</small></button>`).join('')||'<p>今天有什么想记下来的？</p>'}<div class="actions">${button('＋ 写日记','diary-edit')}${button('全部日志','tab','data-key="life" data-value="diary"')}</div>` )}</div><div class="room-finance">${panel('CREDITS.terminal',`<input aria-label="账目月份" type="month" data-change="finance-month" value="${ui.financeMonth}"><div class="balance"><p>收入 <b>¥ ${income.toFixed(2)}</b></p><p>支出 <b>¥ ${expense.toFixed(2)}</b></p><p>结余 <b>¥ ${(income-expense).toFixed(2)}</b></p></div>${[['Food','饮食'],['Shopping','购物'],['Transport','交通'],['Study','学习'],['Entertainment','娱乐'],['Other','其他']].map(([c,label])=>{const amount=items.filter(f=>f.kind==='expense'&&f.category===c).reduce((a,f)=>a+f.amount,0);return `<div class="expense-line"><span>${label}</span><span>¥ ${amount.toFixed(2)}</span>${bar(expense?amount/expense*100:0,label,'magenta')}</div>`}).join('')}<div class="actions">${button('＋ 记账','finance-new')}${button('管理账目','tab','data-key="life" data-value="finance"')}</div>` )}</div></section>`}
